// 隔離Debugの対象PIDから取得したグリッドボタンを渡す検証案。未実行。
import ApplicationServices
import XCTest

func verifyGridButtonAX(_ grid: AXUIElement) {
    var raw: CFTypeRef?
    XCTAssertEqual(AXUIElementCopyAttributeValue(grid, kAXSizeAttribute as CFString, &raw), .success)
    guard let raw else { XCTFail("AXSizeなし"); return }
    guard CFGetTypeID(raw) == AXValueGetTypeID() else { XCTFail("AXSizeの型不一致"); return }
    var size = CGSize.zero
    XCTAssertTrue(AXValueGetValue(raw as! AXValue, .cgSize, &size))
    XCTAssertEqual(size.width, 30, accuracy: 0.1)
    XCTAssertEqual(size.height, 24, accuracy: 0.1)
    XCTAssertEqual(AXUIElementSetAttributeValue(grid, kAXFocusedAttribute as CFString, kCFBooleanTrue), .success)
    XCTAssertEqual(AXUIElementPerformAction(grid, kAXPressAction as CFString), .success)
}
